def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(cells) == 4:
                objects.append(cells)

    out = [[0] * 6 for _ in range(3)]
    for cells in objects:
        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        # In a T tetromino, the lone cell is the stem tip.
        counts_r = {r: rows.count(r) for r in set(rows)}
        counts_c = {c: cols.count(c) for c in set(cols)}
        bar_row = next(r for r, n in counts_r.items() if n == 3)
        tip_row = next(r for r, n in counts_r.items() if n == 1)
        value = 3 if tip_row < bar_row else 1

        center_col = sum(cols) / 4
        out_col = min(5, int(center_col * 6 / w))
        center_row = sum(rows) / 4
        out_row = 0 if center_row < h / 2 else 2
        out[out_row][out_col] = value

    return out
